-- setup.sql — sample database for: Prove your SQL Server is ready: a Unicode table
-- Drops and re-creates the database DBI202_CL (a scratch database used only by Code Lab exercises), then the tables + rows.
-- Xoá và tạo lại CSDL DBI202_CL (CSDL nháp chỉ dùng cho bài Code Lab), rồi tạo bảng + dữ liệu. Chạy lại bất cứ lúc nào để làm sạch.
USE master;
GO
IF DB_ID(N'DBI202_CL') IS NOT NULL
BEGIN
    ALTER DATABASE DBI202_CL SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE DBI202_CL;
END
GO
CREATE DATABASE DBI202_CL;
GO
USE DBI202_CL;
GO
-- (no sample tables — this exercise starts from an empty database)
SELECT CAST(SERVERPROPERTY('ProductVersion') AS NVARCHAR(30)) AS ServerVersion, CAST(SERVERPROPERTY('Edition') AS NVARCHAR(60)) AS Edition;
GO
PRINT N'setup.sql: database DBI202_CL ready.';

-- check.sql — self-check for: Prove your SQL Server is ready: a Unicode table
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 3 checks ──────────';

-- CHECK 1: The server is SQL Server 2019 or newer
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF(CAST(PARSENAME(CAST(SERVERPROPERTY(''ProductVersion'') AS NVARCHAR(30)), 4) AS INT) >= 15, 1, 0);
SET @info = CONCAT(N''your version is '', CAST(SERVERPROPERTY(''ProductVersion'') AS NVARCHAR(30)), N'' — install SQL Server 2019/2022 (or Azure SQL Edge on Apple Silicon)'');',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. The server is SQL Server 2019 or newer | Máy chủ là SQL Server 2019 trở lên'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. The server is SQL Server 2019 or newer | Máy chủ là SQL Server 2019 trở lên', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 2: Table HelloDbi has id INT (primary key) and msg NVARCHAR(50) NOT NULL
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF(OBJECT_ID(N''dbo.HelloDbi'', N''U'') IS NOT NULL
  AND EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.HelloDbi'') AND c.name = N''id'' AND t.name = N''int'')
  AND EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id WHERE c.object_id = OBJECT_ID(N''dbo.HelloDbi'') AND c.name = N''msg'' AND t.name = N''nvarchar'' AND c.max_length = 100 AND c.is_nullable = 0)
  AND EXISTS (SELECT 1 FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id WHERE i.object_id = OBJECT_ID(N''dbo.HelloDbi'') AND i.is_primary_key = 1 AND c.name = N''id''), 1, 0);
SET @info = N''expected HelloDbi(id INT PRIMARY KEY, msg NVARCHAR(50) NOT NULL)'';',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. Table HelloDbi has id INT (primary key) and msg NVARCHAR(50) NOT NULL | Bảng HelloDbi có id INT (khoá chính) và msg NVARCHAR(50) NOT NULL'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. Table HelloDbi has id INT (primary key) and msg NVARCHAR(50) NOT NULL | Bảng HelloDbi có id INT (khoá chính) và msg NVARCHAR(50) NOT NULL', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: Row 1 holds the Vietnamese text exactly (no "?")
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @m NVARCHAR(50) = (SELECT msg FROM dbo.HelloDbi WHERE id = 1);
SET @ok = IIF(@m = N''Xin chào, tôi học DBI202'' COLLATE Latin1_General_BIN2, 1, 0);
SET @info = CONCAT(N''found: '', COALESCE(@m, N''(no row 1)''), N'' — did you forget the N in N''''...''''?'');',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. Row 1 holds the Vietnamese text exactly (no "?") | Dòng 1 giữ đúng chữ tiếng Việt (không thành "?")'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. Row 1 holds the Vietnamese text exactly (no "?") | Dòng 1 giữ đúng chữ tiếng Việt (không thành "?")', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

PRINT N'──────────────────────────────────────';
IF @fail = 0 PRINT CONCAT(N'ALL ', @pass, N' CHECKS PASSED — go back to Code Lab and press "Mark as solved".');
ELSE PRINT CONCAT(@pass, N' passed, ', @fail, N' FAILED — fix solution.sql, then run setup.sql, solution.sql, check.sql again.');
SELECT CASE WHEN @fail = 0 THEN N'ALL CHECKS PASSED' ELSE N'NOT YET' END AS Result, @pass AS Passed, @fail AS Failed;
IF @fail > 0 RAISERROR(N'%d check(s) failed', 16, 1, @fail);

